{
  "name": "House Rent Calculator & Receipt Pro",
  "description": "A professional house rent management tool to calculate bills, generate digital receipts, and print them as PDFs."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BillData {
  tenantName: string;
  rentMonth: string;
  paymentDate: string;
  houseRent: number;
  gasBill: number;
  electricityBill: number;
  wifiBill: number;
  garbageBill: number;
  previousDue: number;
  paidAmount: number;
}

export interface CalculationResult extends BillData {
  totalBill: number;
  remainingDue: number;
}

import React from 'react';

interface InputGroupProps {
  label: string;
  id: string;
  type?: string;
  value: string | number;
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => void;
  placeholder?: string;
  options?: string[];
  required?: boolean;
}

export const InputGroup: React.FC<InputGroupProps> = ({
  label,
  id,
  type = "number",
  value,
  onChange,
  placeholder,
  options,
  required = true
}) => {
  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-semibold text-slate-700">
        {label}
      </label>
      {type === "select" ? (
        <select
          id={id}
          value={value}
          onChange={onChange}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
        >
          <option value="">Select Month</option>
          {options?.map((opt) => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      ) : (
        <input
          id={id}
          type={type}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
          min={type === "number" ? 0 : undefined}
        />
      )}
    </div>
  );
};

import React from 'react';
import { CalculationResult } from '../types';

interface ReceiptCardProps {
  data: CalculationResult;
  onPrint: () => void;
}

export const ReceiptCard: React.FC<ReceiptCardProps> = ({ data, onPrint }) => {
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val).replace('$', '৳ ');
  };

  const rows = [
    { label: 'House Rent', value: data.houseRent },
    { label: 'Gas Bill', value: data.gasBill },
    { label: 'Electricity Bill', value: data.electricityBill },
    { label: 'WiFi Bill', value: data.wifiBill },
    { label: 'Garbage Bill', value: data.garbageBill },
    { label: 'Previous Due', value: data.previousDue },
  ];

  return (
    <div id="receipt-section" className="bg-white p-6 md:p-10 rounded-2xl shadow-xl border border-slate-100 max-w-2xl mx-auto my-8">
      {/* Receipt Header */}
      <div className="text-center border-b border-dashed border-slate-300 pb-6 mb-6">
        <h2 className="text-3xl font-bold text-blue-600 mb-2 uppercase tracking-wide">Rent Receipt</h2>
        <p className="text-slate-500 text-sm">Official Housing Payment Confirmation</p>
      </div>

      {/* Primary Details */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8 text-sm">
        <div>
          <p className="text-slate-400 uppercase text-xs font-bold tracking-tighter">Tenant Name</p>
          <p className="text-lg font-semibold text-slate-800">{data.tenantName}</p>
        </div>
        <div className="md:text-right">
          <p className="text-slate-400 uppercase text-xs font-bold tracking-tighter">Date & Month</p>
          <p className="text-lg font-semibold text-slate-800">{data.paymentDate} | {data.rentMonth}</p>
        </div>
      </div>

      {/* Bill Breakdown */}
      <div className="space-y-3 mb-8">
        {rows.map((row, idx) => (
          <div key={idx} className="flex justify-between items-center py-2 border-b border-slate-50 text-slate-600">
            <span>{row.label}</span>
            <span className="font-medium text-slate-800">{formatCurrency(row.value)}</span>
          </div>
        ))}
      </div>

      {/* Totals Section */}
      <div className="bg-slate-50 rounded-xl p-6 space-y-4">
        <div className="flex justify-between items-center text-slate-700">
          <span className="font-semibold">Total Bill</span>
          <span className="text-xl font-bold">{formatCurrency(data.totalBill)}</span>
        </div>
        <div className="flex justify-between items-center text-green-600">
          <span className="font-semibold">Paid Amount</span>
          <span className="text-xl font-bold text-green-700">-{formatCurrency(data.paidAmount)}</span>
        </div>
        <div className="flex justify-between items-center border-t border-slate-200 pt-4 text-blue-700">
          <span className="text-lg font-extrabold uppercase tracking-tight">Remaining Due</span>
          <span className="text-2xl font-black">{formatCurrency(data.remainingDue)}</span>
        </div>
      </div>

      {/* Footer */}
      <div className="mt-10 flex justify-between items-end">
        <div className="text-[10px] text-slate-400 max-w-[200px]">
          Note: This is a computer generated receipt. Please keep it for your records.
        </div>
        <div className="text-center w-32">
          <div className="border-t border-slate-300 pt-2 text-xs font-semibold text-slate-500 uppercase">
            Signature
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="mt-10 flex justify-center no-print">
        <button
          onClick={onPrint}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-full font-bold shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5 active:scale-95"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M5 4v3H4a2 2 0 00-2 2v3a2 2 0 002 2h1v2a2 2 0 002 2h6a2 2 0 002-2v-2h1a2 2 0 002-2V9a2 2 0 00-2-2h-1V4a2 2 0 00-2-2H7a2 2 0 00-2 2zm8 0H7v3h6V4zm0 8H7v4h6v-4z" clipRule="evenodd" />
          </svg>
          Print Receipt / Save PDF
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { BillData, CalculationResult } from './types';
import { InputGroup } from './components/InputGroup';
import { ReceiptCard } from './components/ReceiptCard';

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const App: React.FC = () => {
  const [formData, setFormData] = useState<BillData>({
    tenantName: '',
    rentMonth: '',
    paymentDate: new Date().toISOString().split('T')[0],
    houseRent: 0,
    gasBill: 0,
    electricityBill: 0,
    wifiBill: 0,
    garbageBill: 0,
    previousDue: 0,
    paidAmount: 0,
  });

  const [result, setResult] = useState<CalculationResult | null>(null);

  const handleInputChange = (id: keyof BillData, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      [id]: value
    }));
  };

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    const totalBill = 
      Number(formData.houseRent) + 
      Number(formData.gasBill) + 
      Number(formData.electricityBill) + 
      Number(formData.wifiBill) + 
      Number(formData.garbageBill) + 
      Number(formData.previousDue);

    const remainingDue = totalBill - Number(formData.paidAmount);

    setResult({
      ...formData,
      totalBill,
      remainingDue
    });

    // Smooth scroll to result
    setTimeout(() => {
      document.getElementById('receipt-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        {/* Header Section */}
        <header className="text-center mb-10 no-print">
          <div className="inline-flex items-center justify-center p-3 bg-blue-100 rounded-2xl mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
          </div>
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">
            RentPro <span className="text-blue-600">Calculator</span>
          </h1>
          <p className="mt-2 text-slate-600 text-lg">Manage house rent and generate professional receipts instantly.</p>
        </header>

        {/* Form Section */}
        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 no-print">
          <form onSubmit={calculate} className="p-8 md:p-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
              {/* Left Column: Basic Info */}
              <div className="space-y-6">
                <h3 className="text-xl font-bold text-slate-800 border-l-4 border-blue-600 pl-3">General Information</h3>
                <InputGroup
                  label="Tenant Name"
                  id="tenantName"
                  type="text"
                  value={formData.tenantName}
                  onChange={(e) => handleInputChange('tenantName', e.target.value)}
                  placeholder="Enter tenant full name"
                />
                <InputGroup
                  label="Rent Month"
                  id="rentMonth"
                  type="select"
                  value={formData.rentMonth}
                  options={MONTHS}
                  onChange={(e) => handleInputChange('rentMonth', e.target.value)}
                />
                <InputGroup
                  label="Payment Date"
                  id="paymentDate"
                  type="date"
                  value={formData.paymentDate}
                  onChange={(e) => handleInputChange('paymentDate', e.target.value)}
                />
              </div>

              {/* Right Column: Bills */}
              <div className="space-y-6">
                <h3 className="text-xl font-bold text-slate-800 border-l-4 border-emerald-600 pl-3">Bill Details</h3>
                <div className="grid grid-cols-2 gap-4">
                  <InputGroup
                    label="House Rent"
                    id="houseRent"
                    value={formData.houseRent}
                    onChange={(e) => handleInputChange('houseRent', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Gas Bill"
                    id="gasBill"
                    value={formData.gasBill}
                    onChange={(e) => handleInputChange('gasBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Electricity"
                    id="electricityBill"
                    value={formData.electricityBill}
                    onChange={(e) => handleInputChange('electricityBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="WiFi Bill"
                    id="wifiBill"
                    value={formData.wifiBill}
                    onChange={(e) => handleInputChange('wifiBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Garbage Bill"
                    id="garbageBill"
                    value={formData.garbageBill}
                    onChange={(e) => handleInputChange('garbageBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Previous Due"
                    id="previousDue"
                    value={formData.previousDue}
                    onChange={(e) => handleInputChange('previousDue', parseFloat(e.target.value) || 0)}
                  />
                </div>
                <div className="pt-4 border-t border-slate-100">
                  <InputGroup
                    label="Paid Amount / Deposit"
                    id="paidAmount"
                    value={formData.paidAmount}
                    onChange={(e) => handleInputChange('paidAmount', parseFloat(e.target.value) || 0)}
                  />
                </div>
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-lg transition-all transform hover:scale-[1.01] active:scale-95 text-lg"
            >
              Calculate & Generate Receipt
            </button>
          </form>
        </div>

        {/* Result Receipt Section */}
        {result && (
          <div className="mt-12 animate-in fade-in slide-in-from-bottom-10 duration-700">
            <ReceiptCard data={result} onPrint={handlePrint} />
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React from 'react';

interface InputGroupProps {
  label: string;
  id: string;
  type?: string;
  value: string | number;
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => void;
  placeholder?: string;
  options?: string[];
  required?: boolean;
}

export const InputGroup: React.FC<InputGroupProps> = ({
  label,
  id,
  type = "number",
  value,
  onChange,
  placeholder,
  options,
  required = true
}) => {
  // Logic to handle value display to avoid "0" always persisting when user types
  const displayValue = type === "number" && value === 0 ? "" : value;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-semibold text-slate-700">
        {label}
