        <select
          id={id}
          value={value}
          onChange={onChange}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
        >
          <option value="">Select Month</option>
          {options?.map((opt) => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      ) : (
        <input
          id={id}
          type={type}
          value={displayValue}
          onChange={onChange}
          placeholder={placeholder || (type === "number" ? "0" : "")}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
          min={type === "number" ? 0 : undefined}
          onFocus={(e) => type === "number" && e.target.select()}
        />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { BillData, CalculationResult } from './types';
import { InputGroup } from './components/InputGroup';
import { ReceiptCard } from './components/ReceiptCard';

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const App: React.FC = () => {
  const [formData, setFormData] = useState<BillData>({
    tenantName: '',
    rentMonth: '',
    paymentDate: new Date().toISOString().split('T')[0],
    houseRent: 0,
    gasBill: 0,
    electricityBill: 0,
    wifiBill: 0,
    garbageBill: 0,
    previousDue: 0,
    paidAmount: 0,
  });

  const [result, setResult] = useState<CalculationResult | null>(null);

  const handleInputChange = (id: keyof BillData, value: string | number) => {
    setFormData(prev => ({
      ...prev,
      [id]: value
    }));
  };

  // Real-time calculation of total bill excluding current payment
  const liveTotalBill = useMemo(() => {
    return (
      Number(formData.houseRent) + 
      Number(formData.gasBill) + 
      Number(formData.electricityBill) + 
      Number(formData.wifiBill) + 
      Number(formData.garbageBill) + 
      Number(formData.previousDue)
    );
  }, [formData]);

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    const remainingDue = liveTotalBill - Number(formData.paidAmount);

    setResult({
      ...formData,
      totalBill: liveTotalBill,
      remainingDue
    });

    // Smooth scroll to result
    setTimeout(() => {
      document.getElementById('receipt-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const handlePrint = () => {
    window.print();
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val).replace('$', '৳ ');
  };

  return (
    <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto">
        {/* Header Section */}
        <header className="text-center mb-10 no-print">
