              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
          </div>
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">
            RentPro <span className="text-blue-600">Calculator</span>
          </h1>
          <p className="mt-2 text-slate-600 text-lg">Manage house rent and generate professional receipts instantly.</p>
        </header>

        {/* Form Section */}
        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 no-print">
          <form onSubmit={calculate} className="p-8 md:p-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
              {/* Left Column: Basic Info */}
              <div className="space-y-6">
                <h3 className="text-xl font-bold text-slate-800 border-l-4 border-blue-600 pl-3">General Information</h3>
                <InputGroup
                  label="Tenant Name"
                  id="tenantName"
                  type="text"
                  value={formData.tenantName}
                  onChange={(e) => handleInputChange('tenantName', e.target.value)}
                  placeholder="Enter tenant full name"
                />
                <InputGroup
                  label="Rent Month"
                  id="rentMonth"
                  type="select"
                  value={formData.rentMonth}
                  options={MONTHS}
                  onChange={(e) => handleInputChange('rentMonth', e.target.value)}
                />
                <InputGroup
                  label="Payment Date"
                  id="paymentDate"
                  type="date"
                  value={formData.paymentDate}
                  onChange={(e) => handleInputChange('paymentDate', e.target.value)}
                />
              </div>

              {/* Right Column: Bills */}
              <div className="space-y-6">
                <h3 className="text-xl font-bold text-slate-800 border-l-4 border-emerald-600 pl-3">Bill Details</h3>
                <div className="grid grid-cols-2 gap-4">
                  <InputGroup
                    label="House Rent"
                    id="houseRent"
                    value={formData.houseRent}
                    onChange={(e) => handleInputChange('houseRent', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Gas Bill"
                    id="gasBill"
                    value={formData.gasBill}
                    onChange={(e) => handleInputChange('gasBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Electricity"
                    id="electricityBill"
                    value={formData.electricityBill}
                    onChange={(e) => handleInputChange('electricityBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="WiFi Bill"
                    id="wifiBill"
                    value={formData.wifiBill}
                    onChange={(e) => handleInputChange('wifiBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Garbage Bill"
                    id="garbageBill"
                    value={formData.garbageBill}
                    onChange={(e) => handleInputChange('garbageBill', parseFloat(e.target.value) || 0)}
                  />
                  <InputGroup
                    label="Previous Due"
                    id="previousDue"
                    value={formData.previousDue}
                    onChange={(e) => handleInputChange('previousDue', parseFloat(e.target.value) || 0)}
                  />
                </div>

                {/* Real-time Total Display */}
                <div className="pt-4 border-t border-slate-100">
                  <div className="flex justify-between items-center mb-4 bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <span className="text-sm font-bold text-slate-600 uppercase tracking-tight">Estimated Total Bill:</span>
