import React from 'react';

interface InputGroupProps {
  label: string;
  id: string;
  type?: string;
  value: string | number;
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => void;
  placeholder?: string;
  options?: string[];
  required?: boolean;
}

export const InputGroup: React.FC<InputGroupProps> = ({
  label,
  id,
  type = "number",
  value,
  onChange,
  placeholder,
  options,
  required = true
}) => {
  // Logic to handle value display: 
  // If user clears the input, we show empty string. 
  // If value is 0 and it's not a focus event, we might want to show "0" for clarity in some fields, 
  // but to satisfy "auto delete 0", we treat 0 as empty string for display in the input box.
  const displayValue = type === "number" && value === 0 ? "" : value;

  // Allow negative values only for 'previousDue'
  const minVal = (id === 'previousDue') ? undefined : 0;

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-semibold text-slate-700">
        {label}
      </label>
      {type === "select" ? (
        <select
          id={id}
          value={value}
          onChange={onChange}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
        >
          <option value="">Select Month</option>
          {options?.map((opt) => (
            <option key={opt} value={opt}>{opt}</option>
          ))}
        </select>
      ) : (
        <input
          id={id}
          type={type}
          value={displayValue}
          onChange={onChange}
          placeholder={placeholder || (type === "number" ? "0" : "")}
          className="w-full px-4 py-2.5 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all bg-white"
          required={required}
          min={type === "number" ? minVal : undefined}
          step="any"
          onFocus={(e) => {
            if (type === "number") {
              e.target.select();
            }
          }}
        />
      )}
    </div>
  );
};

