          >
            Calculate
          </button>
        </nav>

        {/* Landlord Tab */}
        {activeTab === 'landlord' && (
          <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 animate-in fade-in duration-300">
            <h2 className="text-2xl font-black text-slate-800 mb-6 border-b pb-4">House Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">House Name</label>
                <p className="text-xl font-bold text-slate-800">{landlord.houseName}</p>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">House Number</label>
                <p className="text-xl font-bold text-slate-800">{landlord.houseNo}</p>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">Landlord Name</label>
                <p className="text-xl font-bold text-slate-800">{landlord.name}</p>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">Mobile Number</label>
                <p className="text-xl font-bold text-slate-800">{landlord.mobile}</p>
              </div>
            </div>
          </div>
        )}

        {/* Tenants Tab */}
        {activeTab === 'tenants' && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden animate-in fade-in duration-300">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-2xl font-black text-slate-800">Current Tenants</h2>
              <span className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-xs font-bold">{TENANTS.length} Active</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] font-black">
                  <tr>
                    <th className="px-6 py-4">Flat</th>
                    <th className="px-6 py-4">Name</th>
                    <th className="px-6 py-4">Phone</th>
                    <th className="px-6 py-4">Address</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
