                      <td className="px-6 py-4 text-slate-800 font-medium">{tenant.name}</td>
                      <td className="px-6 py-4 text-slate-600 font-mono text-sm">{tenant.phone}</td>
                      <td className="px-6 py-4 text-slate-500 text-sm">{tenant.address}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Calculator Tab */}
        {activeTab === 'calculator' && (
          <div className="space-y-12 animate-in fade-in duration-300">
            <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden no-print">
              <form onSubmit={calculate} className="p-8 md:p-12">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">

                  {/* Left Column: Tenant Selection & Date */}
                  <div className="space-y-6">
                    <h3 className="text-lg font-black text-slate-800 border-l-4 border-blue-600 pl-3 uppercase tracking-wider">Tenant Selection</h3>

                    <div className="flex flex-col gap-1.5">
                      <label className="text-sm font-semibold text-slate-700">Select Flat / Tenant</label>
                      <select 
                        className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                        value={formData.tenantId}
                        onChange={(e) => handleInputChange('tenantId', e.target.value)}
                        required
                      >
                        <option value="">Choose a Tenant...</option>
                        {TENANTS.map(t => (
                          <option key={t.id} value={t.id}>[{t.flatNo}] {t.name}</option>
                        ))}
                      </select>
                    </div>

                    <InputGroup
                      label="Rent Month"
                      id="rentMonth"
                      type="select"
                      value={formData.rentMonth}
                      options={MONTHS}
                      onChange={(e) => handleInputChange('rentMonth', e.target.value)}
                    />
                    <InputGroup
                      label="Payment Date"
                      id="paymentDate"
                      type="date"
                      value={formData.paymentDate}
                      onChange={(e) => handleInputChange('paymentDate', e.target.value)}
                    />
                  </div>

