                        value={formData.paidAmount}
                        onChange={(e) => handleInputChange('paidAmount', parseFloat(e.target.value) || 0)}
                      />
                    </div>
                  </div>
                </div>

                <button
                  type="submit"
                  className="w-full mt-10 bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all transform hover:scale-[1.01] active:scale-95 text-xl uppercase tracking-widest"
                >
                  Generate Receipt
                </button>
              </form>
            </div>

            {/* Receipt Result */}
            {result && selectedTenant && (
              <ReceiptCard 
                data={result} 
                landlord={landlord} 
                flatNo={selectedTenant.flatNo}
                onPrint={() => window.print()} 
              />
            )}
          </div>
        )}

      </div>
    </div>
  );
};

export default App;

