            <button 
              onClick={() => setActiveTab('calculator')}
              className={`px-6 py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'calculator' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <span>🧮</span> Calculator
            </button>
            <button 
              onClick={() => setActiveTab('tenants')}
              className={`px-6 py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'tenants' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <span>👥</span> Tenants
            </button>
            <button 
              onClick={() => setActiveTab('landlord')}
              className={`px-6 py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'landlord' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <span>🏠</span> House Info
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4">
