                <div className="h-12 w-1.5 bg-emerald-500 rounded-full"></div>
                <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Tenant Directory</h2>
              </div>
              <span className="bg-emerald-50 text-emerald-600 px-5 py-2 rounded-2xl text-xs font-extrabold uppercase tracking-widest border border-emerald-100">{TENANTS.length} Resident(s)</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
