  { id: 6, name: "Towfik", address: "Shahzadpur", phone: "01800000000", flatNo: "3C" },
  { id: 7, name: "Amina", address: "Shahzadpur", phone: "01300000000", flatNo: "4C" },
  { id: 8, name: "Liton", address: "Shahzadpur", phone: "01819000000", flatNo: "1B" },
];

const LANDLORD_DEFAULT: LandlordInfo = {
  houseName: "Hazi Vila",
  houseNo: "619",
  name: "Md. Nazrul Islam",
  mobile: "01712011254"
};

type Tab = 'landlord' | 'tenants' | 'calculator';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('calculator');
  const [landlord] = useState<LandlordInfo>(LANDLORD_DEFAULT);

  const initialFormData: BillData = {
    tenantId: '',
    tenantName: '',
    rentMonth: MONTHS[new Date().getMonth()],
    paymentDate: new Date().toISOString().split('T')[0],
    houseRent: 0,
    gasBill: 0,
    electricityBill: 0,
    wifiBill: 0,
    garbageBill: 0,
    previousDue: 0,
    paidAmount: 0,
  };

  const [formData, setFormData] = useState<BillData>(initialFormData);
  const [result, setResult] = useState<CalculationResult | null>(null);

  const handleInputChange = (id: keyof BillData, value: string | number) => {
    if (id === 'tenantId') {
      const tenant = TENANTS.find(t => t.id === Number(value));
      setFormData(prev => ({
        ...prev,
        tenantId: value,
        tenantName: tenant ? tenant.name : ''
      }));
    } else {
      setFormData(prev => ({ ...prev, [id]: value }));
    }
  };

  const handleReset = () => {
    setFormData(initialFormData);
    setResult(null);
  };

  const liveTotalBill = useMemo(() => {
    const rent = Number(formData.houseRent) || 0;
    const gas = Number(formData.gasBill) || 0;
    const electricity = Number(formData.electricityBill) || 0;
    const wifi = Number(formData.wifiBill) || 0;
    const garbage = Number(formData.garbageBill) || 0;
    const prevDue = Number(formData.previousDue) || 0;
    return rent + gas + electricity + wifi + garbage + prevDue;
  }, [formData]);

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.tenantId) {
      alert("Please select a tenant first!");
      return;
    }

    const paid = Number(formData.paidAmount) || 0;
    const total = liveTotalBill;
    const due = total - paid;

    setResult({
      ...formData,
      totalBill: total,
      remainingDue: due
    });

    setTimeout(() => {
      document.getElementById('receipt-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
