              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                  <tr>
                    <th className="px-10 py-5">Unit</th>
                    <th className="px-10 py-5">Name</th>
                    <th className="px-10 py-5">Contact</th>
                    <th className="px-10 py-5">Location</th>
                    <th className="px-10 py-5 text-center">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {tenants.map(tenant => (
                    <tr key={tenant.id} className="hover:bg-slate-50/80 transition-colors group">
                      <td className="px-10 py-6 font-bold text-indigo-600 text-lg">{tenant.flatNo}</td>
                      <td className="px-10 py-6 text-slate-800 font-bold">{tenant.name}</td>
                      <td className="px-10 py-6 text-slate-600 font-mono font-medium text-sm">{tenant.phone}</td>
                      <td className="px-10 py-6 text-slate-400 text-sm font-medium">{tenant.address}</td>
                      <td className="px-10 py-6">
                        <div className="flex justify-center gap-2">
                          <button 
                            onClick={() => setEditingTenant(tenant)}
                            className="p-2.5 rounded-xl bg-slate-100 text-slate-500 hover:bg-indigo-600 hover:text-white transition-all"
                            title="Edit"
                          >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                            </svg>
                          </button>
                          <button 
                            onClick={() => handleDeleteTenant(tenant.id)}
                            className="p-2.5 rounded-xl bg-slate-100 text-slate-500 hover:bg-red-600 hover:text-white transition-all"
                            title="Delete"
                          >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Modal for Edit/Add */}
            {(editingTenant || isAdding) && (
              <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/50">
                    <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">
                      {editingTenant ? 'Edit Tenant' : 'Add New Resident'}
                    </h3>
                    <button onClick={() => {setEditingTenant(null); setIsAdding(false);}} className="text-slate-400 hover:text-slate-600">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                  <form onSubmit={handleUpdateTenant} className="p-8 space-y-5">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1.5">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Flat Unit</label>
                        <input name="flatNo" defaultValue={editingTenant?.flatNo} placeholder="e.g. 2A" required className="w-full px-5 py-3 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-bold text-slate-800" />
                      </div>
                      <div className="space-y-1.5">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Phone Number</label>
                        <input name="phone" defaultValue={editingTenant?.phone} placeholder="01XXX-XXXXXX" required className="w-full px-5 py-3 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-bold text-slate-800" />
                      </div>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
                      <input name="name" defaultValue={editingTenant?.name} placeholder="Tenant's Legal Name" required className="w-full px-5 py-3 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-bold text-slate-800" />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Building/Area Address</label>
                      <input name="address" defaultValue={editingTenant?.address} placeholder="Address Details" required className="w-full px-5 py-3 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-bold text-slate-800" />
                    </div>
                    <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-indigo-100 mt-4 hover:bg-indigo-700 transition-all">
                      {editingTenant ? 'Update Tenant Record' : 'Save Resident Details'}
                    </button>
                  </form>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'calculator' && (
          <div className="space-y-12 animate-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white rounded-[2.5rem] shadow-2xl shadow-indigo-100/50 border border-slate-100 overflow-hidden no-print">
              <form onSubmit={calculate} className="p-8 md:p-12">
                <div className="flex justify-between items-center mb-10">
                  <div className="flex items-center gap-4">
                    <div className="h-12 w-1.5 bg-indigo-600 rounded-full"></div>
                    <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Bill Calculator</h2>
                  </div>
                  <button 
                    type="button" 
                    onClick={handleReset}
                    className="text-slate-400 hover:text-red-500 transition-colors text-xs font-bold uppercase tracking-widest flex items-center gap-2 px-4 py-2 hover:bg-red-50 rounded-xl"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                    </svg>
                    Clear Form
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  <div className="space-y-8">
                    <div className="bg-slate-50/50 p-8 rounded-3xl border border-slate-100 space-y-6">
                      <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.2em] mb-4">Resident Info</h3>

                      <div className="flex flex-col gap-1.5">
                        <label className="text-xs font-bold text-slate-500 uppercase ml-1">Select Unit / Name</label>
                        <select 
                          className="w-full px-5 py-3.5 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 focus:ring-0 outline-none transition-all appearance-none bg-white font-bold text-slate-800 cursor-pointer"
                          value={formData.tenantId}
                          onChange={(e) => handleInputChange('tenantId', e.target.value)}
                          required
                        >
                          <option value="">Choose Occupant...</option>
                          {tenants.map(t => (
                            <option key={t.id} value={t.id}>[{t.flatNo}] — {t.name}</option>
                          ))}
                        </select>
                      </div>

                      <InputGroup
                        label="Billing Month"
                        id="rentMonth"
                        type="select"
                        value={formData.rentMonth}
                        options={MONTHS}
                        onChange={(e) => handleInputChange('rentMonth', e.target.value)}
                      />
                      <InputGroup
                        label="Settlement Date"
                        id="paymentDate"
                        type="date"
                        value={formData.paymentDate}
                        onChange={(e) => handleInputChange('paymentDate', e.target.value)}
                      />
                    </div>
                  </div>

                  <div className="space-y-8">
                    <div className="bg-indigo-50/30 p-8 rounded-3xl border border-indigo-100 space-y-6">
                      <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.2em] mb-4">Utility Breakdown</h3>
                      <div className="grid grid-cols-2 gap-5">
                        <InputGroup label="Monthly Rent" id="houseRent" value={formData.houseRent} onChange={(e) => handleInputChange('houseRent', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Gas Line" id="gasBill" value={formData.gasBill} onChange={(e) => handleInputChange('gasBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Electricity" id="electricityBill" value={formData.electricityBill} onChange={(e) => handleInputChange('electricityBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="WiFi Service" id="wifiBill" value={formData.wifiBill} onChange={(e) => handleInputChange('wifiBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Waste Disp." id="garbageBill" value={formData.garbageBill} onChange={(e) => handleInputChange('garbageBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Prev. Balance" id="previousDue" value={formData.previousDue} onChange={(e) => handleInputChange('previousDue', parseFloat(e.target.value) || 0)} />
                      </div>
                    </div>

                    <div className="bg-slate-900 rounded-[2rem] p-8 shadow-xl shadow-slate-200">
                      <div className="flex justify-between items-center mb-6">
                        <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">Gross Total:</span>
                        <span className="text-3xl font-black text-white font-mono">{formatCurrency(liveTotalBill)}</span>
                      </div>

                      <div className="space-y-2">
                        <label className="text-xs font-bold text-slate-500 uppercase ml-1">Payment Received</label>
                        <input
                          type="number"
                          value={formData.paidAmount === 0 ? "" : formData.paidAmount}
                          onChange={(e) => handleInputChange('paidAmount', parseFloat(e.target.value) || 0)}
                          placeholder="Enter Amount Paid..."
                          className="w-full bg-slate-800/50 border-2 border-slate-800 rounded-2xl px-5 py-3 text-emerald-400 font-bold placeholder:text-slate-600 outline-none focus:border-emerald-500/30 transition-all text-xl"
                          onFocus={(e) => e.target.select()}
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <button
                  type="submit"
                  className="w-full mt-12 bg-indigo-600 hover:bg-indigo-700 text-white font-extrabold py-5 rounded-3xl shadow-2xl shadow-indigo-200 transition-all transform hover:-translate-y-1 active:scale-[0.98] text-xl uppercase tracking-[0.2em]"
                >
                  Generate Digital Receipt
                </button>
              </form>
            </div>

            {result && selectedTenant && (
              <div className="animate-in fade-in zoom-in duration-500 pb-20">
                <ReceiptCard 
                  data={result} 
                  landlord={landlord} 
                  flatNo={selectedTenant.flatNo}
                />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-12 mb-8 text-center no-print">
        <div className="flex flex-col items-center gap-2">
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">
            &copy; {new Date().getFullYear()} Property Management System &bull; Secure & Digital
          </p>
          <div className="h-px w-12 bg-slate-200 my-2"></div>
          <p className="text-indigo-600 text-sm font-extrabold tracking-tight">
            Created By: <span className="text-slate-900">Md. Ruhul Amin</span>
          </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { BillData, CalculationResult, LandlordInfo, Tenant } from './types';
import { InputGroup } from './components/InputGroup';
import { ReceiptCard } from './components/ReceiptCard';

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const INITIAL_TENANTS: Tenant[] = [
  { id: 1, name: "Md. Rasedul Islam", address: "Shahzadpur", phone: "01718-876029", flatNo: "2A" },
  { id: 2, name: "Habib", address: "Shahzadpur", phone: "01700000000", flatNo: "2B" },
  { id: 3, name: "Unknown", address: "Shahzadpur", phone: "01100000000", flatNo: "2C" },
  { id: 4, name: "Jamal", address: "Shahzadpur", phone: "01714-511730", flatNo: "3A" },
  { id: 5, name: "Abu Sayed", address: "Shahzadpur", phone: "0180000000", flatNo: "3B" },
  { id: 6, name: "Towfik", address: "Shahzadpur", phone: "01800000000", flatNo: "3C" },
  { id: 7, name: "Amina", address: "Shahzadpur", phone: "01300000000", flatNo: "4C" },
  { id: 8, name: "Liton", address: "Shahzadpur", phone: "01819000000", flatNo: "1B" },
];

const LANDLORD_DEFAULT: LandlordInfo = {
  houseName: "Hazi Vila",
  houseNo: "619",
  name: "Md. Nazrul Islam",
  mobile: "01712011254"
};

type Tab = 'landlord' | 'tenants' | 'calculator';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('calculator');
  const [landlord] = useState<LandlordInfo>(LANDLORD_DEFAULT);

  const [tenants, setTenants] = useState<Tenant[]>(() => {
    const saved = localStorage.getItem('rentmaster_tenants');
    return saved ? JSON.parse(saved) : INITIAL_TENANTS;
  });

  useEffect(() => {
    localStorage.setItem('rentmaster_tenants', JSON.stringify(tenants));
  }, [tenants]);

  const [editingTenant, setEditingTenant] = useState<Tenant | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  const initialFormData: BillData = {
    tenantId: '',
    tenantName: '',
    rentMonth: MONTHS[new Date().getMonth()],
    paymentDate: new Date().toISOString().split('T')[0],
    houseRent: 0,
    gasBill: 0,
    electricityBill: 0,
    wifiBill: 0,
    garbageBill: 0,
    previousDue: 0,
    paidAmount: 0,
  };

  const [formData, setFormData] = useState<BillData>(initialFormData);
  const [result, setResult] = useState<CalculationResult | null>(null);

  const handleInputChange = (id: keyof BillData, value: string | number) => {
    if (id === 'tenantId') {
      const tenant = tenants.find(t => t.id === Number(value));
      setFormData(prev => ({
        ...prev,
        tenantId: value,
        tenantName: tenant ? tenant.name : ''
      }));
    } else {
      setFormData(prev => ({ ...prev, [id]: value }));
    }
  };

  const handleReset = () => {
    setFormData(initialFormData);
    setResult(null);
  };

  const handleDeleteTenant = (id: number) => {
    if (confirm("Are you sure you want to remove this tenant?")) {
      setTenants(prev => prev.filter(t => t.id !== id));
      if (formData.tenantId === id) handleReset();
    }
  };

  const handleUpdateTenant = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const updated = {
      id: editingTenant?.id || Date.now(),
      name: fd.get('name') as string,
      phone: fd.get('phone') as string,
      address: fd.get('address') as string,
      flatNo: fd.get('flatNo') as string,
    };

    if (editingTenant) {
      setTenants(prev => prev.map(t => t.id === updated.id ? updated : t));
    } else {
      setTenants(prev => [...prev, updated]);
    }
    setEditingTenant(null);
    setIsAdding(false);
  };

  const liveTotalBill = useMemo(() => {
    const rent = Number(formData.houseRent) || 0;
    const gas = Number(formData.gasBill) || 0;
    const electricity = Number(formData.electricityBill) || 0;
    const wifi = Number(formData.wifiBill) || 0;
    const garbage = Number(formData.garbageBill) || 0;
    const prevDue = Number(formData.previousDue) || 0;
    return rent + gas + electricity + wifi + garbage + prevDue;
  }, [formData]);

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.tenantId) {
      alert("Please select a tenant first!");
      return;
    }

    const paid = Number(formData.paidAmount) || 0;
    const total = liveTotalBill;
    const due = total - paid;

    setResult({
      ...formData,
      totalBill: total,
      remainingDue: due
    });

    setTimeout(() => {
      document.getElementById('receipt-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-BD', { style: 'currency', currency: 'BDT' }).format(val).replace('BDT', '৳');
  };

  const selectedTenant = tenants.find(t => t.id === Number(formData.tenantId));

  return (
    <div className="min-h-screen">
      {/* Top Header Navigation */}
      <header className="no-print pt-10 pb-6 px-6 max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 w-14 h-14 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-200">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" viewBox="0 0 20 20" fill="currentColor">
              <path d="M10.707 2.293a1 1 0 00-1.414 0l-7 7a1 1 0 001.414 1.414L4 10.414V17a1 1 0 001 1h2a1 1 0 001-1v-2a1 1 0 011-1h2a1 1 0 011 1v2a1 1 0 001 1h2a1 1 0 001-1v-6.586l.293.293a1 1 0 001.414-1.414l-7-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">RentMaster Pro</h1>
            <p className="text-xs font-black text-indigo-500 uppercase tracking-[0.2em]">{landlord.houseName} Management</p>
          </div>
        </div>

        <nav className="flex bg-white/50 backdrop-blur-md p-1.5 rounded-3xl border border-white shadow-lg">
          {(['calculator', 'tenants', 'landlord'] as const).map((tab) => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100 scale-105' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {tab === 'landlord' ? 'Property' : tab}
            </button>
          ))}
        </nav>
      </header>

      <main className="max-w-5xl mx-auto px-4 py-10">
        {/* Landlord View */}
        {activeTab === 'landlord' && (
          <div className="bg-white rounded-[3rem] p-12 shadow-2xl border border-white animate-in zoom-in-95 duration-500">
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter mb-12">Building Settings</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {[
                { label: 'House Name', value: landlord.houseName, icon: '🏠' },
                { label: 'House Number', value: landlord.houseNo, icon: '📍' },
                { label: 'Proprietor', value: landlord.name, icon: '👤' },
                { label: 'Contact Mobile', value: landlord.mobile, icon: '📱' },
              ].map((item, i) => (
                <div key={i} className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 group hover:border-indigo-200 transition-all">
                  <span className="text-4xl mb-4 block">{item.icon}</span>
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1 block">{item.label}</label>
                  <p className="text-2xl font-black text-slate-800 tracking-tight">{item.value}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Tenants View */}
        {activeTab === 'tenants' && (
          <div className="bg-white rounded-[3rem] shadow-2xl border border-white overflow-hidden animate-in zoom-in-95 duration-500">
            <div className="p-10 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
              <div>
                <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Tenant Directory</h2>
                <p className="text-sm font-bold text-slate-400 mt-2 uppercase tracking-widest">Active Residents: {tenants.length}</p>
              </div>
              <button 
                onClick={() => setIsAdding(true)}
                className="bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2"
              >
                Add New Record
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50/50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                  <tr>
                    <th className="px-10 py-6">Unit</th>
                    <th className="px-10 py-6">Full Name</th>
                    <th className="px-10 py-6">Contact Info</th>
                    <th className="px-10 py-6 text-center">Manage</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {tenants.map(tenant => (
                    <tr key={tenant.id} className="hover:bg-indigo-50/30 transition-all">
                      <td className="px-10 py-8 font-black text-indigo-600 text-2xl tracking-tighter">{tenant.flatNo}</td>
                      <td className="px-10 py-8 text-slate-900 font-extrabold text-lg">{tenant.name}</td>
                      <td className="px-10 py-8">
                        <p className="text-slate-500 font-bold text-sm tracking-tight">{tenant.phone}</p>
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{tenant.address}</p>
                      </td>
                      <td className="px-10 py-8">
                        <div className="flex justify-center gap-3">
                          <button onClick={() => setEditingTenant(tenant)} className="w-12 h-12 rounded-xl bg-slate-100 text-slate-600 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center shadow-sm">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                            </svg>
                          </button>
                          <button onClick={() => handleDeleteTenant(tenant.id)} className="w-12 h-12 rounded-xl bg-slate-100 text-slate-600 hover:bg-red-600 hover:text-white transition-all flex items-center justify-center shadow-sm">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Editor Modal */}
            {(editingTenant || isAdding) && (
              <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-indigo-900/40 backdrop-blur-xl animate-in fade-in duration-300">
                <div className="bg-white w-full max-w-xl rounded-[3rem] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-indigo-50/50">
                    <h3 className="text-2xl font-black text-indigo-900 tracking-tighter uppercase">{editingTenant ? 'Modify Profile' : 'New Entry'}</h3>
                    <button onClick={() => {setEditingTenant(null); setIsAdding(false);}} className="text-slate-400 hover:text-red-500 transition-colors">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                  <form onSubmit={handleUpdateTenant} className="p-10 space-y-6">
                    <div className="grid grid-cols-2 gap-6">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Flat / Unit</label>
                        <input name="flatNo" defaultValue={editingTenant?.flatNo} placeholder="e.g. 5C" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mobile No.</label>
                        <input name="phone" defaultValue={editingTenant?.phone} placeholder="01XXX-XXXXXX" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tenant Full Name</label>
                      <input name="name" defaultValue={editingTenant?.name} placeholder="Enter Legal Name" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Permanent / Area Address</label>
                      <input name="address" defaultValue={editingTenant?.address} placeholder="Details" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
