                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                    Clear All Data
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
                  {/* General Info */}
                  <div className="space-y-10">
                    <div className="bg-indigo-50/50 p-10 rounded-[2.5rem] border border-indigo-100/50 space-y-8">
                      <h3 className="text-xs font-black text-indigo-600 uppercase tracking-[0.3em] ml-1">1. Occupant Selection</h3>

                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Resident Profile</label>
                        <div className="relative">
                          <select 
                            className="w-full px-6 py-4 rounded-2xl border-2 border-white focus:border-indigo-600 focus:ring-0 outline-none transition-all appearance-none bg-white font-extrabold text-slate-900 tracking-tight cursor-pointer shadow-sm"
                            value={formData.tenantId}
                            onChange={(e) => handleInputChange('tenantId', e.target.value)}
                            required
                          >
                            <option value="">Select Resident...</option>
                            {tenants.map(t => (
                              <option key={t.id} value={t.id}>[{t.flatNo}] {t.name}</option>
                            ))}
                          </select>
                          <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-300">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
                            </svg>
                          </div>
                        </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <InputGroup label="Billing Month" id="rentMonth" type="select" value={formData.rentMonth} options={MONTHS} onChange={(e) => handleInputChange('rentMonth', e.target.value)} />
                        <InputGroup label="Payment Date" id="paymentDate" type="date" value={formData.paymentDate} onChange={(e) => handleInputChange('paymentDate', e.target.value)} />
                      </div>
                    </div>
                  </div>

                  {/* Financial Info */}
                  <div className="space-y-10">
                    <div className="bg-slate-900 p-10 rounded-[2.5rem] border border-slate-800 shadow-2xl space-y-8">
                      <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] ml-1">2. Billing Breakdown</h3>
                      <div className="grid grid-cols-2 gap-6">
                        <InputGroup label="Rent" id="houseRent" value={formData.houseRent} onChange={(e) => handleInputChange('houseRent', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Gas" id="gasBill" value={formData.gasBill} onChange={(e) => handleInputChange('gasBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Electric" id="electricityBill" value={formData.electricityBill} onChange={(e) => handleInputChange('electricityBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Internet" id="wifiBill" value={formData.wifiBill} onChange={(e) => handleInputChange('wifiBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Waste" id="garbageBill" value={formData.garbageBill} onChange={(e) => handleInputChange('garbageBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Arrears" id="previousDue" value={formData.previousDue} onChange={(e) => handleInputChange('previousDue', parseFloat(e.target.value) || 0)} />
                      </div>

                      <div className="pt-8 border-t border-slate-800 flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-4xl font-black text-white font-mono tracking-tighter">{formatCurrency(liveTotalBill)}</span>
                      </div>

                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-emerald-500 uppercase tracking-widest ml-1">Collected Payment (BDT)</label>
                        <input
                          type="number"
                          value={formData.paidAmount === 0 ? "" : formData.paidAmount}
                          onChange={(e) => handleInputChange('paidAmount', parseFloat(e.target.value) || 0)}
                          placeholder="Amount Paid..."
                          className="w-full bg-slate-800 border-2 border-slate-700 rounded-2xl px-8 py-5 text-emerald-400 font-black placeholder:text-slate-600 outline-none focus:border-emerald-500 transition-all text-2xl tracking-tighter"
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <button
                  type="submit"
                  className="w-full mt-16 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-6 rounded-[2.5rem] shadow-2xl shadow-indigo-200 transition-all transform hover:-translate-y-2 active:scale-[0.98] text-xl uppercase tracking-[0.2em]"
                >
                  Generate Digital Paper Memo
                </button>
              </form>
            </div>

            {/* Results */}
            {result && selectedTenant && (
              <div className="pb-20">
                <div className="text-center mb-10 no-print">
                  <div className="h-px w-24 bg-indigo-200 mx-auto mb-6"></div>
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.4em]">Preview Digital Invoice</h3>
                </div>
                <ReceiptCard 
                  data={result} 
                  landlord={landlord} 
                  flatNo={selectedTenant.flatNo}
                />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-20 pb-20 text-center no-print">
        <div className="flex flex-col items-center gap-4">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em]">
            Digital Property Asset Management &bull; Enterprise Edition
          </p>
          <div className="flex items-center gap-3">
             <div className="h-px w-8 bg-slate-300"></div>
             <p className="text-slate-800 text-sm font-black tracking-tighter">
              Developed by <span className="text-indigo-600">Md. Ruhul Amin</span>
            </p>
            <div className="h-px w-8 bg-slate-300"></div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';

interface InputGroupProps {
  label: string;
  id: string;
  type?: string;
  value: string | number;
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => void;
  placeholder?: string;
  options?: string[];
  required?: boolean;
}

export const InputGroup: React.FC<InputGroupProps> = ({
  label,
  id,
  type = "number",
  value,
  onChange,
  placeholder,
  options,
  required = true
}) => {
  const isPreviousDue = id === 'previousDue';
  const displayValue = (type === "number" && (value === 0 || value === "0")) 
    ? (isPreviousDue ? "0" : "") 
    : value;

  const minVal = isPreviousDue ? undefined : 0;

  // Use a dark theme if inside a dark container (like the financial breakdown)
  const isFinancial = ['houseRent', 'gasBill', 'electricityBill', 'wifiBill', 'garbageBill', 'previousDue'].includes(id);

  return (
    <div className="flex flex-col gap-2 w-full">
      <label htmlFor={id} className={`text-[10px] font-black uppercase tracking-widest ml-1 ${isFinancial ? 'text-slate-400' : 'text-slate-500'}`}>
        {label}
      </label>
      <div className="relative group">
        {type === "select" ? (
          <div className="relative">
            <select
              id={id}
              value={value}
              onChange={onChange}
              className={`w-full px-6 py-4 rounded-2xl border-2 outline-none transition-all font-extrabold tracking-tight appearance-none cursor-pointer shadow-sm ${
                isFinancial 
                ? 'bg-slate-800 border-slate-700 text-white focus:border-indigo-500' 
                : 'bg-white border-white focus:border-indigo-600 text-slate-900'
              }`}
              required={required}
            >
              <option value="">Choose...</option>
              {options?.map((opt) => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
            <div className={`absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none ${isFinancial ? 'text-slate-500' : 'text-indigo-200'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
              </svg>
            </div>
          </div>
        ) : (
          <input
            id={id}
            type={type}
            value={displayValue}
            onChange={onChange}
            placeholder={placeholder || "0"}
            className={`w-full px-6 py-4 rounded-2xl border-2 outline-none transition-all font-extrabold tracking-tight shadow-sm ${
              isFinancial 
              ? 'bg-slate-800 border-slate-700 text-white placeholder:text-slate-600 focus:border-indigo-500' 
              : 'bg-white border-white focus:border-indigo-600 text-slate-900 placeholder:text-slate-300'
            }`}
            required={required}
            min={type === "number" ? minVal : undefined}
            step="any"
            onFocus={(e) => {
              if (type === "number") {
                e.target.select();
              }
            }}
          />
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { BillData, CalculationResult, LandlordInfo, Tenant } from './types';
import { InputGroup } from './components/InputGroup';
