    previousDue: 0,
    paidAmount: 0,
  };

  const [formData, setFormData] = useState<BillData>(initialFormData);
  const [result, setResult] = useState<CalculationResult | null>(null);

  const handleInputChange = (id: keyof BillData, value: string | number) => {
    if (id === 'tenantId') {
      const tenant = tenants.find(t => t.id === Number(value));
      setFormData(prev => ({
        ...prev,
        tenantId: value,
        tenantName: tenant ? tenant.name : ''
      }));
    } else {
      setFormData(prev => ({ ...prev, [id]: value }));
    }
  };

  const handleReset = () => {
    setFormData(initialFormData);
    setResult(null);
  };

  const handleDeleteTenant = (id: number) => {
    if (confirm("Are you sure you want to remove this tenant?")) {
      setTenants(prev => prev.filter(t => t.id !== id));
      if (formData.tenantId === id) handleReset();
    }
  };

  const handleUpdateTenant = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const updated = {
      id: editingTenant?.id || Date.now(),
      name: fd.get('name') as string,
      phone: fd.get('phone') as string,
      address: fd.get('address') as string,
      flatNo: fd.get('flatNo') as string,
    };

    if (editingTenant) {
      setTenants(prev => prev.map(t => t.id === updated.id ? updated : t));
    } else {
      setTenants(prev => [...prev, updated]);
    }
    setEditingTenant(null);
    setIsAdding(false);
  };

  const liveTotalBill = useMemo(() => {
    const rent = Number(formData.houseRent) || 0;
    const gas = Number(formData.gasBill) || 0;
    const electricity = Number(formData.electricityBill) || 0;
    const wifi = Number(formData.wifiBill) || 0;
    const garbage = Number(formData.garbageBill) || 0;
    const prevDue = Number(formData.previousDue) || 0;
    return rent + gas + electricity + wifi + garbage + prevDue;
  }, [formData]);

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.tenantId) {
      alert("Please select a tenant first!");
      return;
    }

    const paid = Number(formData.paidAmount) || 0;
    const total = liveTotalBill;
    const due = total - paid;

    setResult({
      ...formData,
      totalBill: total,
      remainingDue: due
    });

    setTimeout(() => {
      document.getElementById('receipt-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-BD', { style: 'currency', currency: 'BDT' }).format(val).replace('BDT', '৳');
  };

  const selectedTenant = tenants.find(t => t.id === Number(formData.tenantId));

  return (
    <div className="min-h-screen">
      {/* Top Header Navigation */}
      <header className="no-print pt-10 pb-6 px-6 max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 w-14 h-14 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-200">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" viewBox="0 0 20 20" fill="currentColor">
              <path d="M10.707 2.293a1 1 0 00-1.414 0l-7 7a1 1 0 001.414 1.414L4 10.414V17a1 1 0 001 1h2a1 1 0 001-1v-2a1 1 0 011-1h2a1 1 0 011 1v2a1 1 0 001 1h2a1 1 0 001-1v-6.586l.293.293a1 1 0 001.414-1.414l-7-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">RentMaster Pro</h1>
            <p className="text-xs font-black text-indigo-500 uppercase tracking-[0.2em]">{landlord.houseName} Management</p>
          </div>
        </div>

        <nav className="flex bg-white/50 backdrop-blur-md p-1.5 rounded-3xl border border-white shadow-lg">
          {(['calculator', 'tenants', 'landlord'] as const).map((tab) => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100 scale-105' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {tab === 'landlord' ? 'Property' : tab}
            </button>
          ))}
        </nav>
      </header>

      <main className="max-w-5xl mx-auto px-4 py-10">
        {/* Landlord View */}
        {activeTab === 'landlord' && (
          <div className="bg-white rounded-[3rem] p-12 shadow-2xl border border-white animate-in zoom-in-95 duration-500">
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter mb-12">Building Settings</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {[
                { label: 'House Name', value: landlord.houseName, icon: '🏠' },
                { label: 'House Number', value: landlord.houseNo, icon: '📍' },
                { label: 'Proprietor', value: landlord.name, icon: '👤' },
                { label: 'Contact Mobile', value: landlord.mobile, icon: '📱' },
                { label: 'Full Location', value: landlord.address, icon: '🌎' },
              ].map((item, i) => (
                <div key={i} className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 group hover:border-indigo-200 transition-all">
                  <span className="text-4xl mb-4 block">{item.icon}</span>
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1 block">{item.label}</label>
                  <p className="text-2xl font-black text-slate-800 tracking-tight">{item.value}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Tenants View */}
        {activeTab === 'tenants' && (
          <div className="bg-white rounded-[3rem] shadow-2xl border border-white overflow-hidden animate-in zoom-in-95 duration-500">
            <div className="p-10 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-6">
              <div>
                <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Tenant Directory</h2>
                <p className="text-sm font-bold text-slate-400 mt-2 uppercase tracking-widest">Active Residents: {tenants.length}</p>
              </div>
              <button 
                onClick={() => setIsAdding(true)}
                className="bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2"
              >
                Add New Record
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50/50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                  <tr>
                    <th className="px-10 py-6">Unit</th>
                    <th className="px-10 py-6">Full Name</th>
                    <th className="px-10 py-6">Contact Info</th>
                    <th className="px-10 py-6 text-center">Manage</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {tenants.map(tenant => (
                    <tr key={tenant.id} className="hover:bg-indigo-50/30 transition-all">
                      <td className="px-10 py-8 font-black text-indigo-600 text-2xl tracking-tighter">{tenant.flatNo}</td>
                      <td className="px-10 py-8 text-slate-900 font-extrabold text-lg">{tenant.name}</td>
                      <td className="px-10 py-8">
                        <p className="text-slate-500 font-bold text-sm tracking-tight">{tenant.phone}</p>
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{tenant.address}</p>
                      </td>
                      <td className="px-10 py-8">
                        <div className="flex justify-center gap-3">
                          <button onClick={() => setEditingTenant(tenant)} className="w-12 h-12 rounded-xl bg-slate-100 text-slate-600 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center shadow-sm">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                            </svg>
                          </button>
                          <button onClick={() => handleDeleteTenant(tenant.id)} className="w-12 h-12 rounded-xl bg-slate-100 text-slate-600 hover:bg-red-600 hover:text-white transition-all flex items-center justify-center shadow-sm">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Editor Modal */}
            {(editingTenant || isAdding) && (
              <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-indigo-900/40 backdrop-blur-xl animate-in fade-in duration-300">
                <div className="bg-white w-full max-w-xl rounded-[3rem] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-indigo-50/50">
                    <h3 className="text-2xl font-black text-indigo-900 tracking-tighter uppercase">{editingTenant ? 'Modify Profile' : 'New Entry'}</h3>
                    <button onClick={() => {setEditingTenant(null); setIsAdding(false);}} className="text-slate-400 hover:text-red-500 transition-colors">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                  <form onSubmit={handleUpdateTenant} className="p-10 space-y-6">
                    <div className="grid grid-cols-2 gap-6">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Flat / Unit</label>
                        <input name="flatNo" defaultValue={editingTenant?.flatNo} placeholder="e.g. 5C" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mobile No.</label>
                        <input name="phone" defaultValue={editingTenant?.phone} placeholder="01XXX-XXXXXX" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tenant Full Name</label>
                      <input name="name" defaultValue={editingTenant?.name} placeholder="Enter Legal Name" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Permanent / Area Address</label>
                      <input name="address" defaultValue={editingTenant?.address} placeholder="Details" required className="w-full px-6 py-4 rounded-2xl border-2 border-slate-100 focus:border-indigo-600 outline-none font-extrabold text-slate-800 tracking-tight" />
                    </div>
                    <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-[2rem] shadow-2xl shadow-indigo-200 mt-6 hover:bg-black transition-all text-sm uppercase tracking-[0.2em]">
                      Save Resident Profile
                    </button>
                  </form>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Calculator View */}
        {activeTab === 'calculator' && (
          <div className="space-y-16 animate-in zoom-in-95 duration-500">
            <div className="bg-white rounded-[3.5rem] shadow-3xl border border-white overflow-hidden no-print">
              <form onSubmit={calculate} className="p-10 md:p-16">
                <div className="flex flex-col md:flex-row justify-between items-center mb-16 gap-6">
                  <div>
                    <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Billing Desk</h2>
                    <p className="text-xs font-black text-indigo-500 uppercase tracking-[0.3em] mt-2">Generate Monthly Settlement</p>
                  </div>
                  <button 
                    type="button" 
                    onClick={handleReset}
                    className="group bg-red-50 text-red-500 px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all hover:bg-red-500 hover:text-white flex items-center gap-2"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                    Clear All Data
                  </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
                  {/* General Info */}
                  <div className="space-y-10">
                    <div className="bg-indigo-50/50 p-10 rounded-[2.5rem] border border-indigo-100/50 space-y-8">
                      <h3 className="text-xl font-bold text-indigo-700 tracking-tight ml-1">1. Occupant selection and profile details</h3>

                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Resident Profile</label>
                        <div className="relative">
                          <select 
                            className="w-full px-6 py-4 rounded-2xl border-2 border-white focus:border-indigo-600 focus:ring-0 outline-none transition-all appearance-none bg-white font-extrabold text-slate-900 tracking-tight cursor-pointer shadow-sm"
                            value={formData.tenantId}
                            onChange={(e) => handleInputChange('tenantId', e.target.value)}
                            required
                          >
                            <option value="">Select Resident...</option>
                            {tenants.map(t => (
                              <option key={t.id} value={t.id}>[{t.flatNo}] {t.name}</option>
                            ))}
                          </select>
                          <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-300">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
                            </svg>
                          </div>
                        </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <InputGroup label="Billing Month" id="rentMonth" type="select" value={formData.rentMonth} options={MONTHS} onChange={(e) => handleInputChange('rentMonth', e.target.value)} />
                        <InputGroup label="Payment Date" id="paymentDate" type="date" value={formData.paymentDate} onChange={(e) => handleInputChange('paymentDate', e.target.value)} />
                      </div>
                    </div>
                  </div>

                  {/* Financial Info */}
                  <div className="space-y-10">
                    <div className="bg-slate-800 p-10 rounded-[2.5rem] border border-slate-700 shadow-2xl space-y-8">
                      <h3 className="text-xl font-bold text-slate-200 tracking-tight ml-1">2. Billing breakdown and financial summary</h3>
                      <div className="grid grid-cols-2 gap-6">
                        <InputGroup label="Rent" id="houseRent" value={formData.houseRent} onChange={(e) => handleInputChange('houseRent', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Gas" id="gasBill" value={formData.gasBill} onChange={(e) => handleInputChange('gasBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Electric" id="electricityBill" value={formData.electricityBill} onChange={(e) => handleInputChange('electricityBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Internet" id="wifiBill" value={formData.wifiBill} onChange={(e) => handleInputChange('wifiBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Waste" id="garbageBill" value={formData.garbageBill} onChange={(e) => handleInputChange('garbageBill', parseFloat(e.target.value) || 0)} />
                        <InputGroup label="Arrears" id="previousDue" value={formData.previousDue} onChange={(e) => handleInputChange('previousDue', parseFloat(e.target.value) || 0)} />
                      </div>

                      <div className="pt-8 border-t border-slate-700 flex justify-between items-center">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-4xl font-black text-white font-mono tracking-tighter">{formatCurrency(liveTotalBill)}</span>
                      </div>

                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-emerald-500 uppercase tracking-widest ml-1">Collected Payment (BDT)</label>
                        <input
                          type="number"
                          value={formData.paidAmount === 0 ? "" : formData.paidAmount}
                          onChange={(e) => handleInputChange('paidAmount', parseFloat(e.target.value) || 0)}
                          placeholder="Amount Paid..."
                          className="w-full bg-slate-900 border-2 border-slate-700 rounded-2xl px-8 py-5 text-emerald-400 font-black placeholder:text-slate-600 outline-none focus:border-emerald-500 transition-all text-2xl tracking-tighter"
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <button
                  type="submit"
                  className="w-full mt-16 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-6 rounded-[2.5rem] shadow-2xl shadow-indigo-200 transition-all transform hover:-translate-y-2 active:scale-[0.98] text-xl uppercase tracking-[0.2em]"
                >
                  Generate Digital Paper Memo
                </button>
              </form>
            </div>

            {/* Results */}
            {result && selectedTenant && (
              <div className="pb-20">
                <div className="text-center mb-10 no-print">
                  <div className="h-px w-24 bg-indigo-200 mx-auto mb-6"></div>
                  <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.4em]">Preview Digital Invoice</h3>
                </div>
                <ReceiptCard 
                  data={result} 
                  landlord={landlord} 
                  flatNo={selectedTenant.flatNo}
                />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-20 pb-20 text-center no-print">
        <div className="flex flex-col items-center gap-4">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em]">
            Digital Property Asset Management &bull; Enterprise Edition
          </p>
          <div className="flex items-center gap-3">
             <div className="h-px w-8 bg-slate-300"></div>
             <p className="text-slate-800 text-sm font-black tracking-tighter">
              Developed by <span className="text-indigo-600">Md. Ruhul Amin</span>
            </p>
            <div className="h-px w-8 bg-slate-300"></div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { CalculationResult, LandlordInfo } from '../types';

interface ReceiptCardProps {
  data: CalculationResult;
  landlord: LandlordInfo;
  flatNo: string;
}

declare global {
  interface Window {
    html2canvas: any;
  }
}

export const ReceiptCard: React.FC<ReceiptCardProps> = ({ data, landlord, flatNo }) => {
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-BD', { style: 'currency', currency: 'BDT' }).format(val).replace('BDT', '৳');
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month, day] = dateStr.split('-');
    return `${day}-${month}-${year}`;
  };

  const handleSaveImage = async () => {
    const element = document.getElementById('receipt-section');
    if (!element) return;

    try {
      const canvas = await window.html2canvas(element, {
        scale: 2, // Better resolution
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      const link = document.createElement('a');
      link.download = `Rent_Memo_${data.tenantName.replace(/\s+/g, '_')}_${data.rentMonth}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.9);
      link.click();
    } catch (error) {
      console.error('Error generating image:', error);
      alert('Failed to generate image.');
    }
  };

  const rows = [
    { label: 'Basic House Rent', value: data.houseRent },
    { label: 'Gas Utility Bill', value: data.gasBill },
    { label: 'Electricity Bill', value: data.electricityBill },
    { label: 'WiFi / Internet Service', value: data.wifiBill },
    { label: 'Waste Management (Garbage)', value: data.garbageBill },
    { label: 'Previous Arrears / Due', value: data.previousDue },
  ];

  const isPaid = data.paidAmount > 0;

  return (
    <div className="receipt-container space-y-6">
      <div id="receipt-section" className="receipt-paper mx-auto max-w-2xl bg-white shadow-2xl rounded-sm border border-slate-200 overflow-hidden relative">
        {/* Paid Stamp - Conditional (Middle watermark style) */}
        {isPaid && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-10 opacity-20 transform -rotate-12">
            <div className="border-[8px] border-emerald-600 rounded-3xl p-6 flex flex-col items-center">
              <span className="text-8xl font-black text-emerald-600 uppercase tracking-tighter leading-none">PAID</span>
              <span className="text-xl font-black text-emerald-600 uppercase tracking-[0.5em] mt-2">Successful</span>
            </div>
          </div>
        )}

        <div className="p-8 md:p-12">
          {/* Header */}
          <div className="flex flex-col md:flex-row justify-between items-start border-b-2 border-slate-900 pb-6 mb-8 gap-4">
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight leading-none mb-1">{landlord.houseName}</h2>
              <p className="text-sm font-bold text-indigo-600 uppercase tracking-widest mb-2">Residential Complex</p>
              <div className="text-xs font-semibold text-slate-500 space-y-0.5">
                <p>Location: House No: {landlord.houseNo}, {landlord.address}</p>
                <p>Proprietor: {landlord.name}</p>
                <p>Mobile: {landlord.mobile}</p>
              </div>
            </div>
            <div className="text-right flex flex-col items-end">
              <div className="bg-slate-900 text-white px-4 py-2 text-xl font-black tracking-tighter mb-2">
                MEMO # {Date.now().toString().slice(-6)}
              </div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Digital Invoice</p>
            </div>
          </div>

          {/* Info Grid */}
          <div className="grid grid-cols-2 gap-8 mb-10">
            <div className="border-l-4 border-indigo-500 pl-4">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Bill To Tenant</h4>
              <p className="text-lg font-extrabold text-slate-900 leading-tight">{data.tenantName}</p>
              <p className="text-sm font-bold text-indigo-600">Unit: {flatNo}</p>
            </div>
            <div className="text-right">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Billing Schedule</h4>
              <p className="text-lg font-extrabold text-slate-900 leading-tight">{data.rentMonth}</p>
              <p className="text-sm font-bold text-slate-500">Issued: {formatDate(data.paymentDate)}</p>
            </div>
          </div>

          {/* Table */}
          <table className="w-full mb-10">
            <thead>
              <tr className="border-b-2 border-slate-900">
                <th className="text-left py-3 text-[11px] font-black text-slate-900 uppercase tracking-widest">Description</th>
                <th className="text-right py-3 text-[11px] font-black text-slate-900 uppercase tracking-widest">Amount</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rows.map((row, idx) => (
                <tr key={idx} className="group">
                  <td className="py-4 text-sm font-bold text-slate-600 group-hover:text-slate-900 transition-colors">{row.label}</td>
                  <td className="py-4 text-right font-mono font-bold text-slate-900">
                    {formatCurrency(row.value)}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="border-t-2 border-slate-900 bg-slate-50/50">
                <td className="py-4 px-2 text-sm font-black text-slate-900 uppercase">Gross Total Payable</td>
                <td className="py-4 px-2 text-right font-mono text-xl font-black text-slate-900">{formatCurrency(data.totalBill)}</td>
              </tr>
              <tr className="text-emerald-600">
                <td className="py-4 px-2 text-sm font-bold uppercase">Payment Deposited (-)</td>
                <td className="py-4 px-2 text-right font-mono text-lg font-bold">{formatCurrency(data.paidAmount)}</td>
              </tr>
              <tr className="border-t-4 border-double border-slate-900 bg-indigo-50">
                <td className="py-5 px-4 text-base font-black text-indigo-900 uppercase tracking-tight">Net Outstanding Balance</td>
                <td className="py-5 px-4 text-right font-mono text-2xl font-black text-indigo-900">{formatCurrency(data.remainingDue)}</td>
              </tr>
            </tfoot>
          </table>

          <div className="mt-20 text-center text-[10px] font-bold text-slate-300 uppercase tracking-[0.3em] border-t border-slate-50 pt-6">
            Thank you for being our valued resident
          </div>
        </div>
      </div>

      <div className="flex justify-center items-center no-print pb-10">
        <button 
          onClick={handleSaveImage}
          className="w-full md:w-auto flex items-center justify-center gap-3 bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all transform hover:-translate-y-1 shadow-xl shadow-indigo-100"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          Save Memo as JPG Image
        </button>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { BillData, CalculationResult, LandlordInfo, Tenant } from './types';
import { InputGroup } from './components/InputGroup';
import { ReceiptCard } from './components/ReceiptCard';

const MONTHS = [
